// Original exercises informed by question types in the supplied papers.
const grade7steps=[
{title:'Who does the word refer to?',zh:'人称、物主与指代',map:['Subject → she / he / they','Before a noun → her / his / their','After a verb → her / him / them'],insight:'First find the role of the blank. “She is kind” needs a subject; “her book” needs ownership. A familiar topic can still hide a different word form.',questions:[
['___ is my new classmate. (Mei)','She',['She','Her','Hers'],'A subject comes before “is”.'],
['This is ___ notebook. (belonging to Mei)','her',['she','her','hers'],'A possessive determiner goes before the noun “notebook”.'],
['We like our classmates. We often help ___.','them',['they','their','them'],'After “help”, use an object pronoun.'],
['Jun has a cat. ___ name is Cloud.','Its',['It','Its',"It’s"],'“Its” shows possession. “It’s” means “it is” or “it has”.'],
['Type the missing word: They are students. ___ classroom is bright.','Their',null,'“Their” describes a noun belonging to them.'],
['Type the missing word: I have a friend. ___ name is Lin. (a boy)','His',null,'Before “name”, choose the possessive “his”.']]},
{title:'Make the verb fit the subject',zh:'一般现在时与第三人称单数',map:['I / You / We / They → meet','She / He / It → meets','Does / doesn’t → base verb'],insight:'Do not change every verb in a sentence in the same way. The first verb may need -s; a verb after “does” stays in its base form.',questions:[
['Mei ___ her friends every morning.','meets',['meet','meets','meeting'],'“Mei” is third-person singular, so “meet” becomes “meets”.'],
['My friends ___ football after school.','play',['plays','play','playing'],'Plural subject “friends” takes the base form in the present simple.'],
['Does Lin ___ near the school?','live',['lives','live','living'],'“Does” carries the agreement; the main verb is “live”.'],
['She does not ___ the answer.','know',['knows','knowing','know'],'After “does not”, use the base verb.'],
['Type the missing form: My teacher ___ English. (teach)','teaches',null,'With he/she/it, verbs ending in -ch normally add -es.'],
['Type the missing word: We study together ___ day.','every',null,'“Every day” is a frequency expression with two words.']]},
{title:'Learn the whole expression',zh:'搭配与动词形式',map:['want → to + verb','spend time → verb-ing','make / let + person → base verb'],insight:'A phrase is a reusable unit. Learning only the Chinese translation of “spend” will not tell you why “spend time reading” is correct.',questions:[
['I want ___ my new classmate.','to help',['help','to help','helping'],'Use want + to + base verb.'],
['She spends ten minutes ___ every morning.','reading',['read','to read','reading'],'Use spend + time + verb-ing.'],
['The funny story makes us ___.','laugh',['laugh','laughing','to laugh'],'Use make + person + base verb in this active pattern.'],
['It is fine to make a mistake. Do not laugh ___ someone.','at',['at','for','with'],'“Laugh at” means direct laughter towards someone, often unkindly. “Laugh with” can mean sharing their amusement.'],
['Type the missing word: Reading is good ___ your language development.','for',null,'“Be good for” describes benefit. “Be good at” describes skill.'],
['Type the missing form: We enjoy ___ together. (learn)','learning',null,'Enjoy is followed by the -ing form.']]},
{title:'Use clues across a passage',zh:'完形填空与上下文',map:['Read the whole text → situation','Use grammar → form','Use logic → connection'],insight:'Do not fill each blank in isolation. Contrast, cause and reference may depend on another sentence. Check both meaning and grammar.',questions:[
['Mei lives far from school, ___ she is never late.','but',['because','but','or'],'The second clause contrasts with the difficulty in the first.'],
['We stayed inside ___ it was raining heavily.','because',['because','but','or'],'The rain explains the reason for staying inside.'],
['Our teacher tells jokes. The jokes make ___ laugh.','us',['we','our','us'],'The object of “make” is “us”; the main idea identifies who laughs.'],
['Three classes are before lunch and two are after lunch. We have ___ classes in total.','five',['three','five','six'],'Combine the two pieces of information: 3 + 2 = 5.'],
['Type the missing form: Many ___ of flowers grow here. (kind)','kinds',null,'“Many kinds of” requires a plural noun.'],
['A lesson ends at 4:10. Another word for “ends” here is ___.','finishes',['begins','finishes','opens'],'Use the context to identify the correct sense.']]},
{title:'Find evidence, not just familiar words',zh:'细节、推理与词数限制',map:['Question → what information?','Evidence → which sentence?','Answer → meaning + word limit'],insight:'“When?” and “How long?” require different information. Copying a nearby phrase is not enough. Work out the answer and then obey the word limit.',questions:[
['Jun plays from 4:15 to 5:45. How long does he play? (Choose the duration.)','Ninety minutes',['After school','Ninety minutes','At 4:15'],'The question asks duration: 1 hour 30 minutes, not a time or an activity.'],
['“The room was quiet. Mei smiled and opened her book.” Which inference is best supported?','She seems comfortable reading there',['She hates books','She seems comfortable reading there','She has finished every book'],'The inference must fit the visible evidence; it should not invent a certainty.'],
['A text explains what a dictionary contains, then how to use it. Its main purpose is to ___.','explain a learning tool',['sell every dictionary','explain a learning tool','describe a football match'],'Identify the purpose of the whole passage, not one detail.'],
['“At first he was nervous. After his friends welcomed him, he relaxed.” What changed?','His feelings',['The weather','His feelings','The school address'],'Trace a change across sentences rather than selecting an isolated keyword.'],
['“Four lessons are in the morning; two are in the afternoon.” Type the total as ONE WORD.','six',null,'Use arithmetic from the evidence and obey the one-word limit.'],
['“She studies on Monday, Tuesday, Wednesday, Thursday and Friday.” Type the number of days as ONE WORD.','five',null,'The answer is a number of days. Do not copy a whole sentence.']]},
{title:'Build an accurate short message',zh:'拼写、连贯与写作迁移',map:['Plan → person / school / interests','Build → accurate sentences','Check → forms / spelling / purpose'],insight:'A clear short message does more than list facts. Keep pronouns consistent, link related ideas, and check commonly confused forms before you send it.',questions:[
['Choose the correctly spelled sentence.','I have a friend in my class.',['I have a freind in my class.','I have a friend in my class.','I have a frend in my class.'],'“Friend” is spelled f-r-i-e-n-d.'],
['Choose the correct description of a pet.','It has white fur.',['It is white fur.','It has white fur.','It have white fur.'],'Use “has” for a feature belonging to the animal; “is” for an adjective, such as “white”.'],
['Mei likes tennis. ___ often plays with her sister.','She',['Her','She','His'],'Use a subject pronoun to connect back to Mei.'],
['Choose the natural closing.','Have a nice day!',['Have a nine day!','Have a nice day!','Has a nice day!'],'Check both the base verb in a wish and the spelling “nice”.'],
['Type the missing form: Mei is friendly and ___. (help)','helpful',null,'An adjective is needed after “is”; “helpful” describes a person ready to help.'],
['Type the missing word: I like our school ___ the teachers are kind.','because',null,'Use “because” to link a judgement to a reason.']]}
];
let workshopStep=0,workshopQuestion=null,workshopAnswered=false,workshopTest=null;
function workshopState(){state.workshop??=grade7steps.map(()=>({attempts:0,correct:0,recent:[],passed:false}));return state.workshop}
function workshopUnlocked(i){return i===0||workshopState()[i-1].passed}
function renderWorkshop(){const units=workshopState(),g=grade7steps[workshopStep],u=units[workshopStep];$('#main').innerHTML=`<div class="eyebrow">A CLOSER LOOK · GRADE 7</div><h1>From one small skill to a whole answer.</h1><p class="sub">Original practice informed by your sample papers · 七年级微阶梯</p><div class="worksteps">${grade7steps.map((s,i)=>`<button data-workstep="${i}" ${!workshopUnlocked(i)?'disabled':''} class="${workshopStep===i?'selected':''}">${units[i].passed?'✓ ':''}${i+1}. ${s.zh}${!workshopUnlocked(i)?' · Locked':''}</button>`).join('')}</div><section class="panel"><div class="eyebrow">STEP ${workshopStep+1} / 6</div><h2>${g.title}</h2><p>${g.insight}</p><div class="map"><div class="mapcenter">${g.zh}</div>${g.map.map((x,i)=>`<div class="branch"><b>Connection ${i+1}</b>${x}</div>`).join('')}</div><div class="workprogress"><span>${u.attempts} / ${state.target} scored repetitions</span><span>${u.attempts?Math.round(u.correct/u.attempts*100):0}% accuracy · ${u.passed?'Mastered ✓':'Not yet mastered'}</span></div><div class="progressbar"><i style="width:${Math.min(u.attempts/state.target*100,100)}%"></i></div><div class="readingtools"><button id="workpractice">Practise this step →</button><button id="worktest" ${u.attempts<state.target?'disabled':''}>10-question mastery check</button></div><p class="sub">Complete ${state.target} submissions here and score 8/10 in a separate check before the next step opens. Incorrect answers count as attempts, not correct answers. The bank is small and repeats intentionally.</p><div id="workquestion"></div></section><div class="panel"><h2>What the sample questions reveal</h2><p>The papers combine pronunciation, everyday communication, word forms, expressions, cloze reading, evidence-based answers and short writing. One broad “Grade 7 grammar” section would hide these different demands.</p><a href="grade7-analysis.html" target="_blank" rel="noopener">Read the anonymised screenshot analysis & Chinese sample-paper research ↗</a></div>${workshopStep===5?`<section class="panel"><h2>Put it together: a short message</h2><p>Write 60–80 words introducing an imaginary friend and their school life. Include a hobby, a routine, one reason and a friendly closing. Use imaginary details.</p><textarea id="workwriting" placeholder="Dear Alex,…">${escape(state.workwriting||'')}</textarea><p class="sub">Saved on this device. No automatic writing score: review task coverage, pronouns, verb forms, spelling and paragraph connections with your teacher.</p></section>`:''}`;workshopTest=null;}
function nextWorkshopQuestion(){let qs=grade7steps[workshopStep].questions.filter(q=>q[0]!==workshopQuestion?.[0]);workshopQuestion=qs[Math.floor(Math.random()*qs.length)];workshopAnswered=false;renderWorkshopQuestion()}
function renderWorkshopQuestion(){const q=workshopQuestion;$('#workquestion').innerHTML=`<div class="feedback"><div class="eyebrow">${workshopTest?`MASTERY CHECK · ${workshopTest.answers.length+1} / 10`:'RETRIEVE BEFORE CHECKING'}</div><h3>${escape(q[0])}</h3>${q[2]?`<div class="options">${shuffle(q[2]).map(a=>`<button class="option" data-workanswer="${escape(a)}">${escape(a)}</button>`).join('')}</div>`:'<form id="workform"><label for="worktyped" class="screenreader">Your answer</label><input id="worktyped" type="text" required autocomplete="off" placeholder="Type your answer…"><button class="primary">Submit answer →</button></form>'}<div id="workfeedback" role="status"></div></div>`}
function answerWorkshop(a){if(workshopAnswered||!a.trim())return;workshopAnswered=true;const q=workshopQuestion,ok=a.trim().toLowerCase()===q[1].toLowerCase(),u=workshopState()[workshopStep];document.querySelectorAll('[data-workanswer]').forEach(b=>b.disabled=true);if($('#worktyped')){$('#worktyped').disabled=true;$('#workform button').disabled=true}if(workshopTest){workshopTest.answers.push(ok);workshopTest.responses.push({q:q[0],a,answer:q[1],why:q[3]});if(workshopTest.answers.length===10){const n=workshopTest.answers.filter(Boolean).length;if(n>=8){u.passed=true;save()}$('#workquestion').innerHTML=`<div class="feedback"><h2>${n}/10 · ${n>=8?'Step mastered':'Keep practising'}</h2><p>${n>=8?'The next step is available.':'Review the corrections and try again after practice.'}</p>${workshopTest.responses.map((r,i)=>`<details><summary>${workshopTest.answers[i]?'✓':'↻'} ${escape(r.q)}</summary><p>Your answer: ${escape(r.a)}<br>Answer: ${escape(r.answer)}<br>${escape(r.why)}</p></details>`).join('')}<button class="primary" id="workback" style="margin-top:15px">Back to workshop →</button></div>`;workshopTest=null;return}$('#workfeedback').innerHTML='<button class="primary" id="worknext" style="margin-top:15px">Next question →</button>';return}u.attempts++;u.correct+=Number(ok);u.recent??=[];u.recent.push(ok);u.recent=u.recent.slice(-10);save();const checkButton=document.querySelector('#worktest');if(checkButton)checkButton.disabled=u.attempts<state.target;const progress=document.querySelector('.workprogress');if(progress)progress.innerHTML=`<span>${u.attempts} / ${state.target} scored repetitions</span><span>${Math.round(u.correct/u.attempts*100)}% accuracy · ${u.passed?'Mastered ✓':'Not yet mastered'}</span>`;$('#workfeedback').innerHTML=`<p><b>${ok?'✓ Correct.':'Try this connection.'}</b> ${escape(q[3])}<br>Answer: ${escape(q[1])}</p><p>${u.attempts} / ${state.target} attempts · ${u.correct} correct</p><button class="primary" id="worknext">Next question →</button>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.workstep!==undefined){const i=Number(b.dataset.workstep);if(workshopUnlocked(i)){workshopStep=i;renderWorkshop()}}if(b.id==='workpractice'){workshopTest=null;nextWorkshopQuestion()}if(b.id==='worktest'&&workshopState()[workshopStep].attempts>=state.target){const qs=grade7steps[workshopStep].questions;workshopTest={answers:[],responses:[],questions:shuffle([...qs,...qs]).slice(0,10)};workshopQuestion=workshopTest.questions[0];workshopAnswered=false;renderWorkshopQuestion()}if(b.dataset.workanswer!==undefined)answerWorkshop(b.dataset.workanswer);if(b.id==='worknext'){if(workshopTest){workshopQuestion=workshopTest.questions[workshopTest.answers.length];workshopAnswered=false;renderWorkshopQuestion()}else nextWorkshopQuestion()}if(b.id==='workback')renderWorkshop()});document.addEventListener('submit',e=>{if(e.target.id==='workform'){e.preventDefault();answerWorkshop($('#worktyped').value)}});document.addEventListener('input',e=>{if(e.target.id==='workwriting'){state.workwriting=e.target.value;save()}});
